(()=>{
const $=id=>document.getElementById(id),nameDialog=$('name-dialog'),nameInput=$('user-name'),installDialog=$('install-dialog');
let installPrompt=null,installReady=false,editing=false;
function greet(){const name=typeof state.profile?.name==='string'?state.profile.name:'';$('greeting').textContent=name?`Olá, ${name}!`:'Olá!';$('profile-initial').textContent=name?Array.from(name)[0].toLocaleUpperCase('pt-BR'):'●';}
function askName(edit=false){editing=edit;nameInput.value=state.profile?.name||'';nameDialog.showModal();}
nameDialog.addEventListener('cancel',e=>{if(!editing)e.preventDefault()});
$('name-form').onsubmit=e=>{e.preventDefault();const name=nameInput.value.trim().replace(/\s+/g,' ');if(!name){nameInput.setCustomValidity('Digite seu nome.');nameInput.reportValidity();return}nameInput.setCustomValidity('');const old=state.profile;state.profile={...old,name};if(save()){greet();nameDialog.close();notify(`Tudo pronto, ${name}!`)}else state.profile=old;};
nameInput.oninput=()=>nameInput.setCustomValidity('');$('profile-button').onclick=()=>askName(true);
const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
const activeTweens=new WeakMap();
function tweenMoney(el,to){if(!el)return;const from=Number(el.dataset.cents)||0;cancelAnimationFrame(activeTweens.get(el));el.dataset.cents=String(to);if(reduced()||from===to){el.textContent=money(to);return}const start=performance.now();function tick(now){const t=Math.min(1,(now-start)/320),ease=1-Math.pow(1-t,3);el.textContent=money(Math.round(from+(to-from)*ease));if(t<1)activeTweens.set(el,requestAnimationFrame(tick));else{el.textContent=money(to);activeTweens.delete(el)}}activeTweens.set(el,requestAnimationFrame(tick))}
function animateIn(){if(reduced())return;document.querySelectorAll('#app .hero,#app .section-head,#app .card').forEach((el,i)=>{el.animate?.([{opacity:0,transform:'translateY(14px)'},{opacity:1,transform:'translateY(0)'}],{duration:380,delay:Math.min(i*45,180),easing:'cubic-bezier(.22,1,.36,1)',fill:'backwards'})})}
let changing=false,lastView='';
function updateCounts(){const es=entries(date);tweenMoney(document.querySelector('#app .money'),sum(es));const dc=$('daily-count');if(dc)dc.innerHTML=`<b>${es.length}</b> OS registradas`;for(const r of state.rates){const minus=document.querySelector(`[data-code="${r.code}"][data-delta="-1"]`);if(!minus)continue;const controls=minus.parentElement,n=count(r.code);minus.disabled=!n;controls.querySelector('.count').textContent=n;tweenMoney(controls.querySelector('.subtotal'),sum(es.filter(e=>e.code===r.code&&e.area===area)))} }
const baseRender=render;render=function(){if(changing&&page==='today'){updateCounts();return}const view=[page,area,date,month].join('|');baseRender();greet();document.querySelectorAll('[data-page]').forEach(b=>b.setAttribute('aria-current',b.dataset.page===page?'page':'false'));document.querySelectorAll('[data-area]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.area===area)));if(view!==lastView)animateIn();lastView=view;};
const baseChange=change;change=function(code,delta){changing=true;try{baseChange(code,delta)}finally{changing=false}const countEl=document.querySelector(`[data-code="${code}"]`)?.parentElement.querySelector('.count');if(countEl&&!reduced()){countEl.getAnimations?.().forEach(a=>a.cancel());countEl.animate?.([{transform:'translateY(3px) scale(.94)',opacity:.65},{transform:'translateY(-2px) scale(1.12)',opacity:1},{transform:'translateY(0) scale(1)'}],{duration:260,easing:'cubic-bezier(.22,1,.36,1)'})}};
document.addEventListener('click',e=>{const b=e.target.closest?.('button');if(!b||b.disabled||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const rect=b.getBoundingClientRect(),r=document.createElement('span');r.className='ripple';r.style.left=(e.clientX?e.clientX-rect.left-9:rect.width/2-9)+'px';r.style.top=(e.clientY?e.clientY-rect.top-9:rect.height/2-9)+'px';b.append(r);setTimeout(()=>r.remove(),600)});
function isInstalled(){return matchMedia('(display-mode: standalone)').matches||navigator.standalone===true}
function updateInstallButton(){const b=$('install-button');b.hidden=isInstalled();b.textContent='Instalar app ↗'}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;updateInstallButton()});
window.addEventListener('appinstalled',()=>{installPrompt=null;updateInstallButton();notify('OS Fácil instalado!')});
$('install-button').onclick=async()=>{if(installPrompt){try{await installPrompt.prompt();const choice=await installPrompt.userChoice;installPrompt=null;if(choice.outcome==='accepted')notify('Confirme a instalação no navegador.')}catch{showInstallHelp()}}else showInstallHelp()};
function showInstallHelp(){const ios=/iPhone|iPad|iPod/.test(navigator.userAgent);$('install-help').innerHTML=ios?'<ol class="install-steps"><li>Abra este endereço no Safari.</li><li>Toque em Compartilhar.</li><li>Escolha <strong>Adicionar à Tela de Início</strong> e confirme.</li></ol>':'<ol class="install-steps"><li>Abra este endereço no Chrome do celular.</li><li>Toque no menu <strong>⋮</strong>.</li><li>Escolha <strong>Instalar aplicativo</strong> ou <strong>Adicionar à tela inicial</strong> e confirme.</li></ol><p>No computador, procure o ícone de instalação na barra de endereço do Chrome ou Edge.</p>';const status=document.createElement('p');status.className='install-status';status.textContent=installReady?'Depois do primeiro acesso, os serviços ficam disponíveis offline neste navegador.':'A instalação depende do suporte do seu navegador. Se a opção não aparecer, atualize a página após o primeiro acesso.';$('install-help').append(status);installDialog.showModal()}
$('close-install').onclick=$('install-confirm').onclick=()=>installDialog.close();
if('serviceWorker' in navigator&&location.protocol!=='file:'){navigator.serviceWorker.register('/sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{installReady=true}).catch(()=>{installReady=false})}
greet();updateInstallButton();
let finished=false;
async function finish(){if(finished)return;finished=true;const splash=$('splash'),bar=$('loading-progress');if(!splash)return;bar.style.width='72%';$('loading-label').textContent='Seu dia está quase pronto…';const logo=splash.querySelector('img');await Promise.race([Promise.allSettled([document.fonts?.ready,logo.decode?.()]),new Promise(resolve=>setTimeout(resolve,1200))]);bar.style.width='100%';$('loading-label').textContent='Tudo pronto!';const elapsed=performance.now()-(window.osBootStarted||0),minimum=state.profile?.name?220:650;await new Promise(resolve=>setTimeout(resolve,Math.max(0,minimum-elapsed)));document.querySelectorAll('header,.welcome,main,.nav').forEach(e=>e.inert=false);splash.classList.add('finished');await new Promise(resolve=>setTimeout(resolve,reduced()?0:420));splash.remove();if(!state.profile?.name)askName();else animateIn();}
document.querySelectorAll('header,.welcome,main,.nav').forEach(e=>e.inert=true);render();
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',finish,{once:true});else finish();
})();
